SELECT FINPROD_ID,SUM(TRADE_AMT) TRADE_AMT FROM TRD_PRODUCT_DEAL
1=1
AND TRADE_DATE <= #{bookDate,jdbcType=DATE}
AND FINPROD_ID = #{bookSetId,jdbcType=VARCHAR}
