SELECT fp.FINPROD_ID finprodId, A.PROD_REGIST_CODE prodRegistCode, fp.FINPROD_ABBR finprodAbbr, rpd.REP_ISSUE_PARTY_ID issuePartyId, si.INSTITUTION_NAME issuePartyName, A.CCY_PURCHASE ccyPurchase, A.PURCHASE_QTY repSumApplyShare,
A.REDEEM_QTY repSumCashShare, A.BALANCE_AMT prodPrdAmt, A.ORIGINAL_VALUE originalValue, A.PRD_VALUE netValue, A.TOTAL_VALUE totalNetNalue, A.VALUE_CCY valueCcy, A.CNY_ORL_VALUE repInitNetvalCny, A.CNY_PRD_VALUE repNetvalCny, A.CNY_TAL_VALUE repSumNetvalCny, A.REA_YIELD reaYield, A.NEW_EXP_YIELD repNewExpectedYield, A.BANK_IMP_INT bankImpInt, B.TDY_ASSET_AMT nonStandBondRatio FROM FIN_PRODUCT fp LEFT JOIN ( SELECT cpds.PROD_ID , cpds.ISSUE_PARTY_ID , cpds.PROD_REGIST_CODE , cpds.CCY_PURCHASE , /* 币种 申购金额 赎回金额 兑付收益 */ cpds.PURCHASE_QTY ,/*累计申购份额*/
cpds.REDEEM_QTY ,/*累计赎回份额*/ cpds.BALANCE_AMT, /*产品余额*/ cpds.ORIGINAL_VALUE, /*初始净值*/ cpds.PRD_VALUE , /*产品净值*/ cpds.TOTAL_VALUE , /*累计净值*/ cpds.VALUE_CCY , /*净值币种*/ cpds.CNY_ORL_VALUE , /*折算人民币初始净值*/ cpds.CNY_PRD_VALUE , /*折算人民币净值*/ cpds.CNY_TAL_VALUE , /*折算人民币累计净值*/ cpds.REA_YIELD , /*实现收益率*/ cpds.NEW_EXP_YIELD , /*最新预期收益率*/ cpds.BANK_IMP_INT , /*银行实现收益*/ cpds.STATUS_DATE, ROW_NUMBER () OVER (PARTITION BY cpds.PROD_ID ORDER BY cpds.STATUS_DATE DESC) NUM FROM CHB_PRD_DEAL_SUB cpds WHERE cpds.STATUS_DATE < #{nextMonthDate,jdbcType=DATE} AND cpds.STATUS_DATE >= #{startDate,jdbcType=DATE}) A ON A.PROD_ID = REPLACE(fp.FINPROD_ID,'F16_','') AND A.NUM = 1 LEFT JOIN BOK_POSITION_PRD B on B.CDATE = A.STATUS_DATE AND B.FINPROD_ID = fp.FINPROD_ID LEFT JOIN REP_PROD_DECLARE rpd ON rpd.REP_FINPROD_ID = fp.FINPROD_ID LEFT JOIN CHB_ORG_REGIST_BANK_CODE corbc ON corbc.REGIST_BANK_CODE = rpd.REP_ISSUE_PARTY_ID LEFT JOIN SYS_INSTITUTION si ON si.INSTITUTION_CODE = corbc.ORG_CODE WHERE fp.FINPROD_ID = #{bookSetId,jdbcType=VARCHAR} AND fp.FINPROD_TYPE2 =#{finprodType,jdbcType=VARCHAR}
